import { readFileSync } from "node:fs";
import {
  CATEGORIES,
  SEASONS,
  FORMALITY_LABEL,
  MATERIALS,
  TEXTURES,
  PATTERNS,
  COLORS,
  COLOR_NAMES,
  colorHex,
} from "../vocab";
import { TagSchema } from "@/lib/ai/tagging-schema";

test("categories and seasons are derived from TagSchema, so they can never drift", () => {
  expect(CATEGORIES).toEqual(TagSchema.shape.category.options);
  expect(SEASONS).toEqual(TagSchema.shape.seasons.element.options);
});

test("formality labels cover 1..5 with a blank zero slot", () => {
  expect(FORMALITY_LABEL).toHaveLength(6);
  expect(FORMALITY_LABEL[0]).toBe("");
  expect(FORMALITY_LABEL[3]).toBe("Smart casual");
});

test("patterns match what the tagger emits", () => {
  expect(PATTERNS).toEqual(["solid", "striped", "check", "print", "other"]);
});

test("textures name knit structure, which material cannot express", () => {
  expect(TEXTURES).toEqual(expect.arrayContaining(["Ribbed", "Cable knit", "Waffle", "Brushed"]));
  // A texture is never a material and vice versa — overlapping the two lists
  // would make the tagger's choice ambiguous. "Other" is the deliberate
  // exception: both lists need their own escape hatch, and a structured-output
  // call with no way to say "none of these" returns a confident wrong answer.
  const overlap = (TEXTURES as readonly string[]).filter((t) =>
    (MATERIALS as readonly string[]).includes(t),
  );
  expect(overlap).toEqual(["Other"]);
});

test("both vocabularies have an escape hatch", () => {
  // A required z.enum with no "Other" forces the model to mislabel rather than
  // admit it cannot tell. TEXTURES originally had none.
  expect(MATERIALS).toContain("Other");
  expect(TEXTURES).toContain("Other");
});

test("the materials the generator's heat rule names all exist in the vocabulary", () => {
  // `HOT_MATERIALS` in lib/generator/rules.ts is matched against `material`.
  // Once material is a constrained enum, any term missing from this list
  // silently stops matching — which is how the rule half-broke before.
  // `quilted` is deliberately absent: it is a TEXTURE, and the heat rule must
  // read texture for it (see item-signals-in-generator, queue #12).
  for (const m of ["Fleece", "Shearling", "Down", "Tweed"]) expect(MATERIALS).toContain(m);
  expect(TEXTURES).toContain("Quilted");
});

test("every colour has a hex a swatch can render", () => {
  for (const c of COLORS) expect(c.hex).toMatch(/^#[0-9a-f]{6}$/i);
  expect(colorHex("navy")).toBeDefined();
  expect(colorHex("NAVY")).toBe(colorHex("navy")); // case-insensitive
  expect(colorHex("not-a-colour")).toBeUndefined();
});

test("the closet vocabulary lives ONLY in vocab.ts", () => {
  // Guards the drift BUGS.md #14 recorded: MATERIALS/CATEGORIES/SEASONS were
  // copy-pasted into both edit screens and neither copy matched the tagger, so
  // the AI could write a material the user could not choose back.
  for (const f of ["components/capture/confirm-form.tsx", "components/closet/item-detail.tsx"]) {
    const src = readFileSync(f, "utf8");
    expect(src, f).not.toMatch(/const\s+(MATERIALS|CATEGORIES|SEASONS|FORMALITY_LABEL)\s*[:=]/);
  }
});

test("the palette and the schema's enum are the same list", () => {
  // COLORS carries the hex and the neutral flag; COLOR_NAMES is what the model
  // is constrained to. Adding a colour to one and not the other would let the
  // tagger emit something with no swatch, or offer a swatch the tagger can
  // never produce — the exact drift this module exists to prevent.
  expect(COLORS.map((c) => c.name).sort()).toEqual([...COLOR_NAMES].sort());
});

test("every palette colour declares whether it is neutral", () => {
  for (const c of COLORS) expect(typeof c.neutral).toBe("boolean");
});

/**
 * Warmth — the signal that decides whether a garment suits today's temperature.
 *
 * The tagger has always written `pattern`, and `texture` arrived with
 * `item-data-completeness`; the generator read neither, so a chunky knit and a
 * fine knit were interchangeable in February. Until now the only thermal read
 * in the product was `seasonFit`, which knows the MONTH, not the weather, and
 * `HOT_MATERIALS`, a keyword list. This module is where warmth becomes real:
 * actual temperature against actual cloth.
 *
 * It is a PREFERENCE. It shifts ranking and can never eliminate a candidate —
 * the same model as outerwear, the colour lean and season, each of which was a
 * hard filter that silently emptied a wardrobe.
 */

/** How the fabric is BUILT. */
const TEXTURE_WARMTH: Record<string, number> = {
  "Open knit": 0.15,
  Seersucker: 0.2,
  "Fine knit": 0.25,
  Flat: 0.4,
  Twill: 0.45,
  Herringbone: 0.55,
  Waffle: 0.6,
  Ribbed: 0.6,
  Terry: 0.65,
  Brushed: 0.7,
  "Cable knit": 0.8,
  Quilted: 0.85,
  Pile: 0.85,
  "Chunky knit": 0.9,
  "Fleece-back": 0.9,
};

/**
 * What the fabric IS. Carries the warmth a weave cannot express — tweed is warm
 * however it is woven, linen is cool however it is knitted.
 *
 * `Stainless steel`, `Gold`, `Silver`, `Rubber` and `Other` are deliberately
 * ABSENT: hardware has no thermal opinion, and a value here would make a watch
 * argue about the weather. They fall through to neutral, which is the truth.
 */
const MATERIAL_WARMTH: Record<string, number> = {
  Linen: 0.15,
  Silk: 0.3,
  Viscose: 0.35,
  Lyocell: 0.35,
  Modal: 0.35,
  Cotton: 0.45,
  Denim: 0.5,
  Canvas: 0.5,
  Nylon: 0.5,
  Polyester: 0.5,
  Leather: 0.55,
  "Faux leather": 0.55,
  Acrylic: 0.6,
  "Merino wool": 0.6,
  // Nap traps air, and it is a cold-season shoe. A small margin over smooth
  // leather on purpose — both are shoes, which barely move the reading anyway.
  Suede: 0.6,
  Wool: 0.65,
  Corduroy: 0.7,
  Cashmere: 0.75,
  Tweed: 0.85,
  Fleece: 0.9,
  Down: 0.95,
  Shearling: 0.95,
};

/**
 * Insulation: warm no matter how it is built, so construction cannot argue it
 * down. This is the set `HOT_MATERIALS` in lib/generator/rules.ts keeps as a
 * hard exclusion; here it also pins the floor of the soft signal.
 */
const INSULATION = new Set(["Fleece", "Down", "Shearling"]);

/** Texture leads, material grounds it. */
const TEXTURE_SHARE = 0.65;

/**
 * 0 = coolest, 1 = warmest, 0.5 = no opinion (untagged or unknown).
 *
 * Reads BOTH dimensions on purpose. Texture alone misses tweed, whose warmth is
 * in the cloth and whose weave a linen shirt also uses. Material alone misses
 * the merino case — a chunky merino knit and a fine merino tee share a fibre and
 * are a season apart. Texture carries the larger share because construction is
 * the stronger signal where both are known, but material sets the floor.
 */
export function itemWarmth(material: string | null, texture: string | null): number {
  const m = material ? MATERIAL_WARMTH[material] : undefined;
  const t = texture ? TEXTURE_WARMTH[texture] : undefined;
  if (m === undefined && t === undefined) return 0.5; // no opinion, never a penalty
  if (t === undefined) return m!;
  if (m === undefined) return t;
  const blended = TEXTURE_SHARE * t + (1 - TEXTURE_SHARE) * m;
  // A fine-knit fleece is still a fleece.
  return material && INSULATION.has(material) ? Math.max(blended, m) : blended;
}

/**
 * How much each slot actually decides whether you are warm.
 *
 * A flat average lets a steel watch and a pair of shoes pull every outfit
 * toward neutral — exactly when the signal should be loudest. Matched by
 * prefix on the lowercased category so DB TitleCase plurals (`Tops`) and the
 * singular fixtures used in scoring tests (`top`) both land.
 */
const CATEGORY_WEIGHT: [string, number][] = [
  ["outerwear", 1.5],
  ["top", 1.2],
  ["bottom", 1],
  ["shoe", 0.6],
  ["accessor", 0.2],
  ["fragrance", 0],
];

function categoryWeight(category?: string | null): number {
  if (!category) return 1; // uncategorised still counts; never silently zeroed
  const c = category.toLowerCase();
  return CATEGORY_WEIGHT.find(([prefix]) => c.startsWith(prefix))?.[1] ?? 1;
}

/**
 * How well a combo's warmth suits the temperature. 0..1, 0.5 = no opinion.
 *
 * `want` maps 25°+ → 0 (want the lightest) and 0° → 1 (want the warmest), and
 * passes through 0.5 at 12.5°.
 *
 * `confidence` is the part that matters and the part a plain `1 - |want - have|`
 * cannot express: that formula's gap between two garments is CONSTANT once
 * `want` sits outside them, so 18° would discriminate exactly as hard as 0°.
 * Fading the whole term toward neutral as the temperature approaches 12.5°
 * gives the intended shape — hardest at the extremes, silent in the middle,
 * where a ribbed knit and a flat shirt are both simply correct and colour,
 * formality and DNA should decide instead.
 */
export function warmthFit(
  items: { category?: string | null; material?: string | null; texture?: string | null }[],
  tempC: number,
): number {
  if (!items.length) return 0.5;
  const want = Math.min(1, Math.max(0, (25 - tempC) / 25));

  let weighted = 0;
  let total = 0;
  for (const i of items) {
    const w = categoryWeight(i.category);
    weighted += w * itemWarmth(i.material ?? null, i.texture ?? null);
    total += w;
  }
  if (total === 0) return 0.5; // nothing in the combo has a thermal say
  const have = weighted / total;

  const confidence = Math.abs(want - 0.5) * 2;
  return 0.5 + confidence * (1 - Math.abs(want - have) - 0.5);
}

/**
 * Warmth — the signal that decides whether a garment suits today's temperature.
 *
 * The tagger has always written `pattern`, and `texture` arrived with
 * `item-data-completeness`; the generator read neither, so a chunky knit and a
 * fine knit were interchangeable in February. Until now the only thermal read
 * in the product was `seasonFit`, which knows the MONTH, not the weather, and
 * `HOT_MATERIALS`, a keyword list. This module is where warmth becomes real:
 * actual temperature against actual cloth.
 *
 * It is a PREFERENCE. It shifts ranking and can never eliminate a candidate —
 * the same model as outerwear, the colour lean and season, each of which was a
 * hard filter that silently emptied a wardrobe.
 */

/**
 * How the fabric is BUILT.
 *
 * Exported for the vocabulary-drift guard in `__tests__/texture.test.ts`: a
 * value the tagger may emit that is missing here scores 0.5 — indistinguishable
 * from the mid-warmth fabrics genuinely worth 0.5 — so the test checks
 * membership, not the number.
 */
export const TEXTURE_WARMTH: Record<string, number> = {
  "Open knit": 0.15,
  Seersucker: 0.2,
  "Fine knit": 0.25,
  Flat: 0.4,
  Twill: 0.45,
  Herringbone: 0.55,
  Waffle: 0.6,
  Ribbed: 0.6,
  Terry: 0.65,
  Brushed: 0.7,
  "Cable knit": 0.8,
  Quilted: 0.85,
  Pile: 0.85,
  "Chunky knit": 0.9,
  "Fleece-back": 0.9,
};

/**
 * What the fabric IS. Carries the warmth a weave cannot express — tweed is warm
 * however it is woven, linen is cool however it is knitted.
 *
 * `Stainless steel`, `Gold`, `Silver`, `Rubber` and `Other` are deliberately
 * ABSENT: hardware has no thermal opinion, and a value here would make a watch
 * argue about the weather. They fall through to neutral, which is the truth.
 */
const MATERIAL_WARMTH: Record<string, number> = {
  Linen: 0.15,
  Silk: 0.3,
  Viscose: 0.35,
  Lyocell: 0.35,
  Modal: 0.35,
  Cotton: 0.45,
  Denim: 0.5,
  Canvas: 0.5,
  Nylon: 0.5,
  Polyester: 0.5,
  Leather: 0.55,
  "Faux leather": 0.55,
  Acrylic: 0.6,
  "Merino wool": 0.6,
  // Nap traps air, and it is a cold-season shoe. A small margin over smooth
  // leather on purpose — both are shoes, which barely move the reading anyway.
  Suede: 0.6,
  Wool: 0.65,
  Corduroy: 0.7,
  Cashmere: 0.75,
  Tweed: 0.85,
  Fleece: 0.9,
  Down: 0.95,
  Shearling: 0.95,
};

/**
 * Insulation: warm no matter how it is built, so construction cannot argue it
 * down. This is the set `HOT_MATERIALS` in lib/generator/rules.ts keeps as a
 * hard exclusion; here it also pins the floor of the soft signal.
 */
const INSULATION = new Set(["Fleece", "Down", "Shearling"]);

/** Texture leads, material grounds it. */
const TEXTURE_SHARE = 0.65;

/**
 * 0 = coolest, 1 = warmest, 0.5 = no opinion (untagged or unknown).
 *
 * Reads BOTH dimensions on purpose. Texture alone misses tweed, whose warmth is
 * in the cloth and whose weave a linen shirt also uses. Material alone misses
 * the merino case — a chunky merino knit and a fine merino tee share a fibre and
 * are a season apart. Texture carries the larger share because construction is
 * the stronger signal where both are known, but material sets the floor.
 */
export function itemWarmth(material: string | null, texture: string | null): number {
  const m = material ? MATERIAL_WARMTH[material] : undefined;
  const t = texture ? TEXTURE_WARMTH[texture] : undefined;
  if (m === undefined && t === undefined) return 0.5; // no opinion, never a penalty
  if (t === undefined) return m!;
  if (m === undefined) return t;
  const blended = TEXTURE_SHARE * t + (1 - TEXTURE_SHARE) * m;
  // A fine-knit fleece is still a fleece.
  return material && INSULATION.has(material) ? Math.max(blended, m) : blended;
}

/**
 * How much each slot actually decides whether you are warm.
 *
 * A flat average lets a steel watch and a pair of shoes pull every outfit
 * toward neutral — exactly when the signal should be loudest. Matched by
 * prefix on the lowercased category so DB TitleCase plurals (`Tops`) and the
 * singular fixtures used in scoring tests (`top`) both land.
 */
const CATEGORY_WEIGHT: [string, number][] = [
  ["outerwear", 1.5],
  ["top", 1.2],
  ["bottom", 1],
  ["shoe", 0.6],
  ["accessor", 0.2],
  ["fragrance", 0],
];

function categoryWeight(category?: string | null): number {
  if (!category) return 1; // uncategorised still counts; never silently zeroed
  const c = category.toLowerCase();
  return CATEGORY_WEIGHT.find(([prefix]) => c.startsWith(prefix))?.[1] ?? 1;
}

/**
 * How well a combo's warmth suits the temperature. 0..1, 0.5 = no opinion.
 *
 * `want` maps 25°+ → 0 (want the lightest) and 0° → 1 (want the warmest), and
 * passes through 0.5 at 12.5°.
 *
 * `confidence` is the part that matters and the part a plain `1 - |want - have|`
 * cannot express: that formula's gap between two garments is CONSTANT once
 * `want` sits outside them, so 18° would discriminate exactly as hard as 0°.
 * Fading the whole term toward neutral as the temperature approaches 12.5°
 * gives the intended shape — hardest at the extremes, silent in the middle,
 * where a ribbed knit and a flat shirt are both simply correct and colour,
 * formality and DNA should decide instead.
 */
export function warmthFit(
  items: { category?: string | null; material?: string | null; texture?: string | null }[],
  tempC: number,
): number {
  if (!items.length) return 0.5;
  const want = Math.min(1, Math.max(0, (25 - tempC) / 25));

  let weighted = 0;
  let total = 0;
  for (const i of items) {
    const w = categoryWeight(i.category);
    weighted += w * itemWarmth(i.material ?? null, i.texture ?? null);
    total += w;
  }
  if (total === 0) return 0.5; // nothing in the combo has a thermal say
  const have = weighted / total;

  const confidence = Math.abs(want - 0.5) * 2;
  return 0.5 + confidence * (1 - Math.abs(want - have) - 0.5);
}

