/**
 * Measurement probe for the item-signals work: does warmth actually change
 * which garments the shortlist offers, on the REAL local closet?
 *
 * Runs the deterministic half of the pipeline (buildCandidates → rankTopN →
 * diversify) at several temperatures. No AI, no cost, no dev server.
 */
import { readFileSync } from "node:fs";
import {
  buildCandidates,
  type CandidateItem,
} from "/Users/1curafu/Desktop/Fitcheck/Fitcheck/lib/generator/candidates";
import { rankTopN } from "/Users/1curafu/Desktop/Fitcheck/Fitcheck/lib/generator/rank";
import { diversify } from "/Users/1curafu/Desktop/Fitcheck/Fitcheck/lib/generator/diversity";

const DIR = "/private/tmp/claude-501/-Users-1curafu-Desktop-Fitcheck-Fitcheck/903d62f8-76c6-4d8e-aaef-442496fb144e/scratchpad";

type Row = CandidateItem & { name: string };
const rows: Row[] = JSON.parse(readFileSync(`${DIR}/closet.json`, "utf8"));
const byId = new Map(rows.map((r) => [r.id, r]));
const label = (id: string) => {
  const r = byId.get(id)!;
  return `${r.name} (${r.material}/${r.texture})`;
};

const items: CandidateItem[] = rows.map((r) => ({
  id: r.id,
  category: r.category,
  colors: r.colors ?? [],
  formality: r.formality,
  seasons: r.seasons ?? [],
  material: r.material,
  texture: r.texture,
  pattern: r.pattern,
}));

const BAND: [number, number] = [1.5, 3.5]; // Everyday
const season = process.argv.includes("--winter") ? "Winter" : "Summer";

for (const tempC of [0, 8, 12, 18, 25, 32]) {
  const args = {
    band: BAND,
    weather: { tempC, rain: false },
    season,
    excludeItemIds: [] as string[],
    maxAccessories: 1,
    rainGuard: true,
  };
  const combos = buildCandidates(items, args);
  const ranked = rankTopN(combos, { aesthetic: [], band: BAND, season, tempC }, combos.length);
  const top = diversify(ranked, 20);

  const tops = top
    .slice(0, 3)
    .map((c) => c.items.find((i) => i.category === "Tops")!)
    .map((i) => label(i.id));

  // How much of the shortlist's top half is knitwear vs flat/linen?
  const knit = top
    .slice(0, 10)
    .filter((c) => c.items.some((i) => i.texture === "Cable knit" || i.texture === "Fine knit"))
    .length;

  console.log(
    `${String(tempC).padStart(3)}°C  combos=${String(combos.length).padStart(3)}  knitwear in top-10: ${knit}/10`,
  );
  for (const t of tops) console.log(`        ${t}`);
}

