input.content:
/**
 * Pattern-clash probe. The real closet is 100% `solid`, so the term cannot
 * fire on it as-is. Two garments are re-tagged IN MEMORY — no DB write, so
 * there is nothing to revert — and the shortlist is measured before and after.
 */
import { readFileSync } from "node:fs";
import {
  buildCandidates,
  type CandidateItem,
} from "/Users/1curafu/Desktop/Fitcheck/Fitcheck/lib/generator/candidates";
import { rankTopN } from "/Users/1curafu/Desktop/Fitcheck/Fitcheck/lib/generator/rank";
import { diversify } from "/Users/1curafu/Desktop/Fitcheck/Fitcheck/lib/generator/diversity";

const DIR = "/private/tmp/claude-501/-Users-1curafu-Desktop-Fitcheck-Fitcheck/903d62f8-76c6-4d8e-aaef-442496fb144e/scratchpad";
type Row = CandidateItem & { name: string };
const rows: Row[] = JSON.parse(readFileSync(`${DIR}/closet.json`, "utf8"));

// One striped top and one checked trouser — the exact pairing the term exists
// to discourage. Both are otherwise strong candidates on this closet.
const STRIPED_TOP = rows.find((r) => r.name === "Oxford shirt" && r.colors.includes("sky"))!;
const CHECKED_BOTTOM = rows.find((r) => r.name === "PLEATED WIDE-LEG TROUSERS")!;

const build = (patterned: boolean): CandidateItem[] =>
  rows.map((r) => ({
    id: r.id,
    category: r.category,
    colors: r.colors ?? [],
    formality: r.formality,
    seasons: r.seasons ?? [],
    material: r.material,
    texture: r.texture,
    pattern: !patterned
      ? r.pattern
      : r.id === STRIPED_TOP.id
        ? "striped"
        : r.id === CHECKED_BOTTOM.id
          ? "check"
          : r.pattern,
  }));

const BAND: [number, number] = [1.5, 3.5];
const args = {
  band: BAND,
  weather: { tempC: 20, rain: false },
  season: "Summer",
  excludeItemIds: [] as string[],
  maxAccessories: 1,
  rainGuard: true,
};

for (const patterned of [false, true]) {
  const items = build(patterned);
  const combos = buildCandidates(items, args);
  const ranked = rankTopN(combos, { aesthetic: [], band: BAND, season: "Summer", tempC: 20 }, combos.length);
  const top = diversify(ranked, 20);

  const clashRank = top.findIndex(
    (c) =>
      c.items.some((i) => i.id === STRIPED_TOP.id) && c.items.some((i) => i.id === CHECKED_BOTTOM.id),
  );
  const soloRank = top.findIndex(
    (c) =>
      c.items.some((i) => i.id === STRIPED_TOP.id) && !c.items.some((i) => i.id === CHECKED_BOTTOM.id),
  );
  console.log(
    `${patterned ? "striped top + checked trouser" : "all solid (as tagged today)      "}  ` +
      `→ both-loud combo at shortlist position ${clashRank === -1 ? "—" : clashRank + 1}` +
      `, one-loud combo at ${soloRank === -1 ? "—" : soloRank + 1}`,
  );
}

