  // on a warm day — even though the photo cannot tell the two apart.
  const warmDay = { ...ctx, season: "Summer", tempC: 24 };
  const summerOk = oneP.map((i) => ({
    ...i,
    texture: "Cable knit",
    material: "Cotton",
    seasons: ["Spring", "Summer"],
