  const winterOnly = oneP.map((i) => ({
    ...i,
    texture: "Cable knit",
    material: "Cotton",
    seasons: ["Autumn", "Winter"],
  }));
  expect(scoreCombo(summerOk, warmDay)).toBeGreaterThan(scoreCombo(winterOnly, warmDay));
});

