/**
 * Where does the black cable-knit crew neck (Autumn/Winter) actually rank,
 * at the temperature the generator used (20°) vs today's real high (34°)?
 *
 * Separates two questions the screenshot conflates:
 *   1. is the warmth signal demoting it at all?
 *   2. does the demotion survive into the 20-slot shortlist the model sees?
 */
import { readFileSync } from "node:fs";
import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
import { personalBand } from "@/lib/generator/rules";
import { rankTopN } from "@/lib/generator/rank";
import { diversify } from "@/lib/generator/diversity";

const DIR = "/private/tmp/claude-501/-Users-1curafu-Desktop-Fitcheck-Fitcheck/903d62f8-76c6-4d8e-aaef-442496fb144e/scratchpad";
const rows = JSON.parse(readFileSync(`${DIR}/closet.json`, "utf8")) as (CandidateItem & {
  name: string;
})[];
const SWEATER = rows.find((r) => r.name === "Cable knit crew neck sweater")!;

const items: CandidateItem[] = rows.map((r) => ({
  id: r.id,
  category: r.category,
  colors: r.colors ?? [],
  formality: r.formality,
  seasons: r.seasons ?? [],
  material: r.material,
  texture: r.texture,
  pattern: r.pattern,
}));

const band = personalBand("work", { formality_min: 3, formality_max: 3 } as never);
const aesthetic = ["Smart Casual"];

for (const tempC of [20, 27, 34]) {
  const args = {
    band,
    weather: { tempC, rain: false },
    season: "Summer",
    excludeItemIds: [] as string[],
    maxAccessories: 1,
    rainGuard: true,
  };
  const combos = buildCandidates(items, args);
  const ranked = rankTopN(combos, { aesthetic, band, season: "Summer", tempC }, combos.length);
  const top20 = diversify(ranked, 20);

  const best = ranked.findIndex((c) => c.items.some((i) => i.id === SWEATER.id));
  const inShortlist = top20.findIndex((c) => c.items.some((i) => i.id === SWEATER.id));
  const eligible = combos.some((c) => c.some((i) => i.id === SWEATER.id));

  console.log(
    `${String(tempC).padStart(2)}°C  eligible=${eligible}  combos=${combos.length}  ` +
      `best rank of a sweater combo: ${best === -1 ? "—" : `#${best + 1}/${ranked.length}`}  ` +
      `→ shortlist slot the model sees: ${inShortlist === -1 ? "NOT SHOWN" : `#${inShortlist + 1}/${top20.length}`}`,
  );
}

