/**
 * What does the shipped pipeline actually do on a cold day?
 * Runs the real weatherRules, laterAdvice and ranking for three day shapes.
 */
import { readFileSync } from "node:fs";
import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
import { personalBand, weatherRules, planningTemp } from "@/lib/generator/rules";
import { rankTopN } from "@/lib/generator/rank";
import { diversify } from "@/lib/generator/diversity";
import { laterAdvice } from "@/lib/weather/advice";

const DIR = "/private/tmp/claude-501/-Users-1curafu-Desktop-Fitcheck-Fitcheck/903d62f8-76c6-4d8e-aaef-442496fb144e/scratchpad";
const rows = JSON.parse(readFileSync(`${DIR}/closet.json`, "utf8")) as (CandidateItem & {
  name: string;
})[];
const items: CandidateItem[] = rows.map((r) => ({
  id: r.id,
  category: r.category,
  colors: r.colors ?? [],
  formality: r.formality,
  seasons: r.seasons ?? [],
  material: r.material,
  texture: r.texture,
  pattern: r.pattern,
}));
const byId = new Map(rows.map((r) => [r.id, r]));

const DAYS = [
  {
    label: "DEEP WINTER  (now -2°, high 3°, low -5°)",
    now: -2, highC: 3, lowC: -5, season: "Winter",
    hourly: [-2, -1, 0, 1].map((t, k) => ({ hh: `0${8 + k}:00`, tempC: t, rain: false, isNow: k === 0 })),
  },
  {
    label: "COLD EVENING (now 8°, high 9°, low 1°) — 18:00",
    now: 8, highC: 9, lowC: 1, season: "Winter",
    hourly: [8, 6, 4, 2].map((t, k) => ({ hh: `${18 + k}:00`, tempC: t, rain: false, isNow: k === 0 })),
  },
  {
    label: "SPRING SWING (now 6°, high 18°, low 5°) — 08:00",
    now: 6, highC: 18, lowC: 5, season: "Spring",
    hourly: [6, 8, 10, 12].map((t, k) => ({ hh: `0${8 + k}:00`, tempC: t, rain: false, isNow: k === 0 })),
  },
];

for (const d of DAYS) {
  const weather = { tempC: d.now, rain: false, highC: d.highC, lowC: d.lowC };
  const rules = weatherRules(weather);
  const band = personalBand("everyday", { formality_min: 3, formality_max: 3 } as never);
  const args = {
    band, weather, season: d.season,
    excludeItemIds: [] as string[], maxAccessories: 1, rainGuard: true,
  };
  const combos = buildCandidates(items, args);
  const ranked = rankTopN(
    combos,
    { aesthetic: [], band, season: d.season, tempC: planningTemp(weather) },
    combos.length,
  );
  const top = diversify(ranked, 20);
  const advice = laterAdvice(d.hourly, "C", d.highC);

  console.log(`\n${d.label}`);
  console.log(`  planningTemp ${planningTemp(weather)}°  needsOuterwear=${rules.needsOuterwear}  maxWarmth=${rules.maxWarmth}`);
  console.log(`  LATER: "${advice.sentence}"`);
  for (const c of top.slice(0, 2)) {
    const names = c.items.map((i) => {
      const r = byId.get(i.id)!;
      return `${r.name} [${r.texture}]`;
    });
    console.log(`    · ${names.join("  +  ")}`);
  }
}

