    band, weather, season: d.season,
    excludeItemIds: [] as string[], maxAccessories: 1, rainGuard: true,
  };
  const combos = buildCandidates(items, args);
  const ranked = rankTopN(
    combos,
    { aesthetic: [], band, season: d.season, tempC: planningTemp(weather) },
    combos.length,
  );
  const top = diversify(ranked, 20);
  const advice = laterAdvice(d.hourly, "C", d.highC);

  console.log(`\n${d.label}`);
  console.log(`  planningTemp ${planningTemp(weather)}°  needsOuterwear=${rules.needsOuterwear}  maxWarmth=${rules.maxWarmth}`);
