13	 * rain later → shell; a big evening drop → jacket; else reassuring.
14	 * Returns the full `sentence` and the `adviceClause` on its own so the UI can
15	 * render the clause in rust (README wraps it in #D69873/600).
16	 *
17	 * @param unit the user's display unit. This sentence is the ONE place a
18	 * temperature is baked into prose server-side, so it cannot be converted at the
19	 * render boundary with everything else. The 5° drop that triggers it is still
20	 * measured in Celsius — the threshold is physics, only the printed number is a
21	 * preference.
22	 *
23	 * @param dayHighC today's high. The generator builds the look for THIS, not for
24	 * the current temperature, so a steep climb needs saying out loud.
25	 */
26	export function laterAdvice(
27	  hourly: HourCell[],
28	  unit: TempUnit = "C",
29	  dayHighC?: number,
30	): { sentence: string; adviceClause: string } {
31	  const rainHour = hourly.find((h) => h.rain);
32	  if (rainHour) {
33	    const adviceClause = "take a shell.";
34	    return { sentence: `Rain from ${rainHour.hh} — ${adviceClause}`, adviceClause };
35	  }
36	
37	  const now = hourly[0]?.tempC ?? 0;
38	
39	  // The look is built for the day's HIGH, so on a morning that climbs steeply it
40	  // will look lighter than the thermometer currently justifies. Say so — this
41	  // sentence is the ONLY thing that explains why, and without it a light outfit
42	  // at 20°C reads as the stylist getting it wrong. It is also the other half of
43	  // the decision: dress for the peak, and be told about the cool start.
44	  if (dayHighC != null && dayHighC - now >= RISE_C) {
45	    const adviceClause = "you're dressed for it.";
46	    return {
47	      sentence: `Up to ${formatTemp(dayHighC, unit)} this afternoon — ${adviceClause}`,
48	      adviceClause,
49	    };
50	  }
51	
52	  const last = hourly[hourly.length - 1]?.tempC ?? now;
53	  if (now - last >= 5) {
54	    const adviceClause = "carry a jacket.";
55	    return { sentence: `Down to ${formatTemp(last, unit)} tonight — ${adviceClause}`, adviceClause };
56	  }
57	
58	  const adviceClause = "no extra layer.";
59	  return { sentence: `Dry through the evening — ${adviceClause}`, adviceClause };
