/** What each occasion is now planned against, on today's real forecast and on an autumn one. */
import { planningTempFor } from "@/lib/weather/planning";
import type { HourCell, UiOccasion } from "@/lib/generator/types";

const cells = (start: number, temps: number[]): HourCell[] =>
  temps.map((t, k) => ({
    hh: `${String(start + k).padStart(2, "0")}:00`,
    tempC: t,
    rain: false,
    isNow: k === 0,
  }));

const DAYS: { label: string; now: number; hours: HourCell[] }[] = [
  {
    label: "TODAY, Rapperswil, asked at 14:00  (real forecast)",
    now: 33,
    hours: cells(14, [33, 34, 35, 34, 34, 32, 29, 27, 26, 25]),
  },
  {
    label: "AN OCTOBER DAY, asked at 14:00",
    now: 17,
    hours: cells(14, [17, 18, 18, 16, 13, 10, 8, 7, 7, 6]),
  },
  {
    label: "THE SAME OCTOBER DAY, asked at 20:00",
    now: 8,
    hours: cells(20, [8, 7, 7, 6]),
  },
];

for (const d of DAYS) {
  console.log(`\n${d.label}   (now ${d.now}°)`);
  for (const o of ["everyday", "work", "weekend", "evening"] as UiOccasion[]) {
    console.log(`   ${o.padEnd(9)} → built for ${planningTempFor(o, d.hours, d.now)}°`);
  }
}

