import {
  eligibleByCategory,
  REQUIRED_CATEGORIES,
  type CandidateItem,
} from "@/lib/generator/candidates";
import { personalBand } from "@/lib/generator/rules";
import type { Weather } from "@/lib/generator/rules";
import type { UiOccasion } from "@/lib/generator/types";

/**
 * The archetypal pieces we know how to recommend. Deliberately small and
 * neutral: the claim is "this unlocks N outfits", and a wilder candidate would
 * inflate N while being something the user would never buy.
 */
export type GapCandidate = { label: string; category: string; colors: string[]; formality: number };

export const GAP_CANDIDATES: GapCandidate[] = [
  { label: "A camel overcoat", category: "Outerwear", colors: ["camel"], formality: 4 },
  { label: "Grey wool trousers", category: "Bottoms", colors: ["grey"], formality: 4 },
  { label: "A navy knit", category: "Tops", colors: ["navy"], formality: 3 },
  { label: "Brown leather loafers", category: "Shoes", colors: ["brown"], formality: 4 },
  { label: "A white oxford shirt", category: "Tops", colors: ["white"], formality: 4 },
  { label: "Dark denim", category: "Bottoms", colors: ["denim"], formality: 2 },
  { label: "Clean white sneakers", category: "Shoes", colors: ["white"], formality: 2 },
];

/**
 * ⚠️ `buildCandidates` stops at `CAP = 200` (lib/generator/candidates.ts). Any
 * closet big enough to exceed that returns 200 both BEFORE and AFTER the
 * hypothetical piece, so every `unlocks` is 0 and `biggestGap` returns null —
 * for exactly the users who would pay for this screen.
 *
 * So do not count combos. Count the product of the eligible required slots,
 * which is what the cap is truncating, and is the number the claim actually
 * means: how many outfits become buildable.
 */
function countCombos(closet: CandidateItem[], occasions: UiOccasion[], weather: Weather): number {
  return occasions.reduce((total, o) => {
    const args = {
      band: personalBand(o, null),
      weather,
      season: undefined as unknown as string,
      excludeItemIds: [],
      maxAccessories: 0,
    };
    const by = eligibleByCategory(closet, args);
    const slots = REQUIRED_CATEGORIES.map((c) => (by[c] ?? []).length);
    // A missing required slot means zero buildable outfits, not a partial count.
    return total + (slots.some((n) => n === 0) ? 0 : slots.reduce((a, b) => a * b, 1));
  }, 0);
}

# Wear Stats Implementation Plan

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** Build `/stats` — closet value, total wears, average cost per wear, most-worn, gathering-dust, and the gap analysis that tells you which single missing piece would unlock the most outfits.

**Architecture:** All of it is aggregation over `items` + `wear_logs`, except the gap analysis, which is a **simulation**: inject a hypothetical garment into the real closet, run the existing candidate builder, and count how many new valid combinations appear. No AI call anywhere on this screen.

**Tech Stack:** TypeScript 6, Supabase, Vitest.

## Global Constraints

- **Depends on** `2026-07-24-outfit-detail-wear-logging.md` (wear data), `2026-07-24-item-data-completeness.md` (prices), and `2026-07-24-seasons-soft-preference.md` (which is where `eligibleByCategory` is created — Task 2 counts slots through it). Without them, five of the six sections are empty.
- **TDD, strictly.** Branch: `feat/wear-stats`. No AI attribution.
- **No AI calls.** Gap analysis is deterministic — it reuses `buildCandidates`.
- Test: `npx vitest run <path>` / `npm run test:run`. Types: `npx tsc --noEmit`. Build: `npm run build`.

## Source

`design_handoff_stylist_generator/Fitcheck.dc.html:737-780`. Review: `docs/design-review-2026-07-24.md` §6.6.

## Explicitly out of scope

**"See curated picks"** (`:767`). The design puts a CTA under the gap card that leads to shoppable
recommendations — an affiliate or commerce surface with no product, legal or partner decision behind it
anywhere in this project. **Do not build it, and do not render a dead button.** The gap card ships
without a CTA until that decision exists. Flagging it here so it is not lost.

## The gap analysis, stated plainly

*"A camel overcoat unlocks 14 new outfits"* is not a query. It is: for each of a fixed set of
**archetypal missing pieces**, add it to the user's closet in memory, re-run `buildCandidates` across
every occasion, and report the piece with the largest increase in valid combinations.

This is honest — the number means exactly what it says, because it is produced by the same code that
builds real outfits. It is also bounded: a fixed candidate list times four occasions is a few dozen
`buildCandidates` calls over an array already in memory.

