    const { needsOuterwear } = weatherRules(weather);
    for (const o of occasions) {
      const by = eligibleByCategory(closet, argsFor(o, weather));
      const slots = REQUIRED_CATEGORIES.map((c) => (by[c] ?? []).length);
      // A missing required slot means zero buildable outfits, not a partial count.
      if (slots.some((n) => n === 0)) continue;
      const base = slots.reduce((a, b) => a * b, 1);
      /**
       * Outerwear is not a REQUIRED category, so it never appears in the slot
       * product — but below 15° `buildCandidates` puts a coat in every combo,
       * which multiplies the day's outfits by the number of coats owned. Without
       * this the cold pass would count the same outfits as the mild one and a
       * coat would still be worth nothing. A closet with no coat is not blocked
       * (outerwear never blocks), so the factor floors at 1.
       */
      const coats = (by["Outerwear"] ?? []).length;
      total += base * (needsOuterwear && coats > 0 ? coats : 1);
    }
  }
  return total;
