  id,
  category,
  colors: ["cream"],
  formality: 3,
  seasons: [],
  material: "Cotton",
  pattern: "solid",
  texture: "Flat",
  ...extra,
});

test("a closet with no bottoms is told a bottom unlocks the most", () => {
